import { describe, expect, it } from "vitest";
import { compileOk } from "./helpers.js";

const sqlOf = (src: string) => compileOk(src).output.sql;

describe("SQL emitter", () => {
  it("emits a complete schema", () => {
    const sql = sqlOf(`model User {
  email: Email unique
  password: Password
  name: Text max 100
  age: Number min 0 max 150 optional
  isAdmin: Bool
  birthday: Date optional
  teamId: ID
}`);
    expect(sql).toMatchInlineSnapshot(`
      "-- Generated by rizolang 0.5.0 from test.rz. Do not edit by hand.
      -- Requires PostgreSQL 13 or newer (uses gen_random_uuid()).
      -- For an existing database, apply the files in migrations/ instead (node migrate.ts).

      BEGIN;

      CREATE TABLE "users" (
        "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        "email" TEXT NOT NULL CONSTRAINT "users_email_key" UNIQUE CONSTRAINT "users_email_check" CHECK (char_length("email") BETWEEN 3 AND 254 AND "email" = lower("email") AND "email" ~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$'),
        -- password: stored only as a salted hash, never as plain text
        "password_hash" TEXT NOT NULL,
        "name" TEXT NOT NULL CONSTRAINT "users_name_check" CHECK (char_length("name") <= 100),
        "age" INTEGER CONSTRAINT "users_age_check" CHECK ("age" BETWEEN 0 AND 150),
        "is_admin" BOOLEAN NOT NULL,
        "birthday" TIMESTAMPTZ,
        "team_id" UUID NOT NULL
      );

      COMMIT;
      "
    `);
  });

  it("emits one table per model, in order", () => {
    const sql = sqlOf("model A {\n  x: Text\n}\nmodel BlogPost {\n  y: Text\n}");
    const a = sql.indexOf('CREATE TABLE "as"');
    const b = sql.indexOf('CREATE TABLE "blog_posts"');
    expect(a).toBeGreaterThan(0);
    expect(b).toBeGreaterThan(a);
  });

  it("emits a lower bound only when min is set", () => {
    expect(sqlOf("model A {\n  x: Text min 2\n}")).toContain('char_length("x") BETWEEN 2 AND 10000');
    expect(sqlOf("model A {\n  n: Number min 1\n}")).toContain('CHECK ("n" >= 1)');
    expect(sqlOf("model A {\n  n: Number max 9\n}")).toContain('CHECK ("n" <= 9)');
  });

  it("omits NOT NULL for optional fields", () => {
    expect(sqlOf("model A {\n  x: Bool optional\n}")).toContain('"x" BOOLEAN\n');
  });

  it("quotes every identifier, including SQL keywords", () => {
    const sql = sqlOf("model Order {\n  select: Text\n  from: Number\n}");
    expect(sql).toContain('CREATE TABLE "orders"');
    expect(sql).toContain('"select" TEXT');
    expect(sql).toContain('"from" INTEGER');
  });
});
